    describe('Fluent => XML => Fluent', () => {
        test('catalog item round-trips correctly', async () => {
            const test = new FluentXmlFluentTest(
                new Project({
                    rootDir: path.resolve(__dirname, 'project'),
                    config: {
                        scope: 'x_sctest',
                        scopeId: '11111111111111111111111111111111',
                    },
                })
            )
            const catalogItemId = test.addId('sc_cat_item', 'test_catalog_item')

            // Add related M2M records
            const catalogId = test.addCoalesceId('sc_cat_item_catalog', {
                sc_cat_item: catalogItemId,
                sc_catalog: 'service-catalog-id',
            })
            const categoryId = test.addCoalesceId('sc_cat_item_category', {
                sc_cat_item: catalogItemId,
                sc_category: 'category-id',
            })
            const topicId = test.addCoalesceId('m2m_connected_content', {
                catalog_item: catalogItemId,
                topic: 'topic-id',
            })
            const availableForCriteriaId = test.addCoalesceId('sc_cat_item_user_criteria_mtom', {
                sc_cat_item: catalogItemId,
                user_criteria: 'available-for-criteria-id',
            })
            const notAvailableForCriteriaId = test.addCoalesceId('sc_cat_item_user_criteria_no_mtom', {
                sc_cat_item: catalogItemId,
                user_criteria: 'not-available-for-criteria-id',
            })
            const varsetId = test.addCoalesceId('io_set_item', {
                sc_cat_item: catalogItemId,
                variable_set: 'varset-id',
                order: '100',
            })
            const priceId = test.addCoalesceId('fx_price', {
                id: catalogItemId,
                field: 'price',
                currencyType: 'USD',
            })
            const recurringPriceId = test.addCoalesceId('fx_price', {
                id: catalogItemId,
                field: 'recurring_price',
                currencyType: 'USD',
            })

            test.addExpectedXmlFileNames(
                `sc_cat_item_${catalogItemId}.xml`,
                `sc_cat_item_catalog_${catalogId}.xml`,
                `sc_cat_item_category_${categoryId}.xml`,
                `m2m_connected_content_${topicId}.xml`,
                `sc_cat_item_user_criteria_mtom_${availableForCriteriaId}.xml`,
                `sc_cat_item_user_criteria_no_mtom_${notAvailableForCriteriaId}.xml`,
                `io_set_item_${varsetId}.xml`,
                `fx_price_${priceId}.xml`,
                `fx_price_${recurringPriceId}.xml`
            )
            test.addFluentFragment(`import { CatalogItem } from '@servicenow/sdk/core'
           CatalogItem({
               $id: Now.ID['test_catalog_item'],
               name: 'test_catalog_item',
               shortDescription: 'A test catalog item',
               description: 'This is a test catalog item',
               order: 100,
               flow: '30f3d26187e92300e0ef0cf888cb0b91',
               requestMethod: 'order',
               availability: 'desktopOnly',
               mandatoryAttachment: false,
               hideAttachment: false,
               catalogs: ['service-catalog-id'],
               categories: ['category-id'],
               assignedTopics: ['topic-id'],
               availableFor: ['available-for-criteria-id'],
               notAvailableFor: ['not-available-for-criteria-id'],
               variableSets: [{variableSet: 'varset-id', order: 100}],
               hideAddToCart: false,
               hideDeliveryTime: false,
               hideQuantitySelector: false,
               hideSaveAsDraft: false,
               pricingDetails: [
                   {
                       amount: 100,
                       currencyType: 'USD',
                       field: 'price',
                   },
                   {
                       amount: 100,
                       currencyType: 'USD',
                       field: 'recurring_price',
                   },
               ],
           })
           `)
            await test.verify()
        })
    })
